	notes: string,
	createdAt: number,
	updatedAt: number,
	lastResearchedAt: number | null,
	lastCommercialActivityAt: number | null,
	revision: number,
	/**  The latest fit assessment (clients). */
	assessment: FitAssessment | null,
	assessments: number,
	activities: Activity[],
